import React from 'react';

const BaoCaoThongKe = () => {
    return (
        <div>
            <h2>📈 Báo cáo hệ thống</h2>
            <div style={{display: 'flex', gap: '20px', marginTop: '20px'}}>
                <div style={{...statBox, background: '#1a237e'}}><h3>1,250</h3><p>Tổng cư dân</p></div>
                <div style={{...statBox, background: '#2e7d32'}}><h3>450</h3><p>Căn hộ đang ở</p></div>
                <div style={{...statBox, background: '#c62828'}}><h3>12</h3><p>Hóa đơn nợ</p></div>
                <div style={{...statBox, background: '#ef6c00'}}><h3>85%</h3><p>Tỷ lệ bãi xe</p></div>
            </div>
        </div>
    );
};

const statBox = { flex: 1, padding: '30px', borderRadius: '15px', color: '#fff', textAlign: 'center' };

export default BaoCaoThongKe;
